export interface CircleShape {
  kind: 'circle'
  cx: number
  cy: number
  r: number
}

export interface RectShape {
  kind: 'rect'
  x: number
  y: number
  width: number
  height: number
}

export type MarkShape = CircleShape | RectShape

export interface ViewBox {
  x: number
  y: number
  width: number
  height: number
}

